INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('notice', 277337, '2023-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8rr3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2n3r.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Notice', 'NOTICE is a 7-10 minute short interactive experience that follows the story of having a panic attack, then using awareness and presence to overcome it. As you get home and start to breathe, you take control over your thoughts. By clicking on each object, you start to become aware of everything in your space and what it means to you. Each object has its own style, musical note and meaning - whether that be the can of soda lying on your desk or the guitar gifted to you from a friend back home.' FROM games WHERE igdb_id = 277337 ON CONFLICT (game_id, language_code) DO NOTHING;
