INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zettai Zetsumei Shoujo: Kokuu no Houteishiki', '30 minutes left until the girl''s death... "Zettai Zetsumei Shoujo" is a short science fiction visual novel that pays homage to "Cold Equations" and "Trolley Problem". You will be forced to make a life choice: a girl who stows away on a spaceship to meet her mother, or a group of victims of a space accident waiting to be rescued. Choose the life you want to save and see the girl''s fate.' FROM games WHERE igdb_id = 268632 ON CONFLICT (game_id, language_code) DO NOTHING;
