INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sweetcore-brews', 254288, '2023-10-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6nju.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2it1.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sweetcore Brews', 'Sweetcore Brews is an otome about a tea-brewing witch called “Milly”, whose dream is to open her own magical tea shop in the city. She is currently an apprentice witch working at an existing magical tea shop where the shopkeeper is rarely around. So Milly manages the shop full-time, practicing daily her new magical teas on her own by using them as solutions for her customers’ lives. She meets two love interests – Zero and Kingsley, both are also magical humans who run their own unique businesses. This game is a slice of life romance where Milly deals with the funny mistakes she makes from her magical teas causing problems, and she falls in love with Zero or Kingsley over time.' FROM games WHERE igdb_id = 254288 ON CONFLICT (game_id, language_code) DO NOTHING;
