INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Phoenix Initiative', 'Play as one of the last surviving humans on a post-apocalyptic Earth, where resources are scarce and danger lurks around every corner. As you scavenge for supplies, fend off vicious enemies, and build a small colony, you must use your wits and combat skills to survive in this harsh new world.' FROM games WHERE igdb_id = 244980 ON CONFLICT (game_id, language_code) DO NOTHING;
