INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Weak Soul', 'Get up. There is no place in this world for those who are weak. I must free the continent from the demons before they get rid of me. Any choice can change someone''s fate. But I will fight as long as the flame of my soul burns.' FROM games WHERE igdb_id = 247741 ON CONFLICT (game_id, language_code) DO NOTHING;
