INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pipe-dreams', 232141, '2023-03-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6agi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5a88.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pipe Dreams', 'This one goes out to the lovers, the believers and the pipe dreamers. All we want is a place that we can be free and live up to our full potential; be something better than ourselves. ‘Pipe Dreams’ is the game where you can power up to the rank of believer and reminisce in the past that never was. Perform space flips in the imagined world of self belief, hang around for a second in the Joy Shop of life, in times that never were. It’s the way of life in a made up fantasy, that we all wanted, but never got.' FROM games WHERE igdb_id = 232141 ON CONFLICT (game_id, language_code) DO NOTHING;
