INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'High School Private Tutor', 'You’re a gifted college student carefully balancing your studies with a part-time tutoring gig until an offer lands in your lap that just might be too good to be true. When your seemingly shy high school tutee falls head over heels for you during the very first lesson together, you’re suddenly thrust into a situation where your head is at war with your heart and your future may just be on the line if word of it ever gets out.' FROM games WHERE igdb_id = 280988 ON CONFLICT (game_id, language_code) DO NOTHING;
