INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astro & Suzy Go to the Beach', 'Astro & Suzy have finally made it to the beach! And the humans are dropping all kinds of yummy things! Hotdogs! Tacos! Hamburgers! Help Astro & Suzy eat all the wasted human beach food before it hits the ground. But watch out for the Mayo! It will ruin the whole day. Make sure to get all the power-ups like Catsup, Mustard, and Salsa! They increase Astro & Suzy’s food bonus multipliers! And don’t miss the ‘dog bone of invincibility’! (Based on a real-life story that hasn’t happened yet)' FROM games WHERE igdb_id = 234284 ON CONFLICT (game_id, language_code) DO NOTHING;
