INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cardania: Epoch Wars', 'Epoch Wars is a live multiplayer strategy game with hundreds of players from around the world. Battle for strategic resources, explore mysterious anomalies, earn EXP and Victory Points for yourself and one of 7 unique Factions, all vying for control of Cardania! Experience a dynamic, shifting map which provides players with a totally fresh experience every 5 days (called an Epoch). Epoch wars utilizes the latest in fast and secure blockchain + NFT technology, so players truly own their lands, cards, and battle units!' FROM games WHERE igdb_id = 254987 ON CONFLICT (game_id, language_code) DO NOTHING;
