INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tetragun', 183881, '2023-05-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6fno.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1atz.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetragun', 'Tetragun is a top-down shooter where you play as a stationary turret and defend yourself against waves of enemies. As you progress through the waves, you will acquire upgrades to help you keep up with the growing strength and numbers of your enemies. The arena is split into 4 quadrants, and your turret will only be able to aim within the confines of the quadrant it is currently in. To aim at enemies outside of your current quadrant, you''ll need to enter rotate mode with RMB and click on the quadrant you would like to rotate to. The goal of the game is to make it as far as possible, and get the highest score you can.' FROM games WHERE igdb_id = 183881 ON CONFLICT (game_id, language_code) DO NOTHING;
