INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rewind to Fear: The Mansion', 'In "Rewind to Fear - The Mansion", you play as a brave woman returning to her late grandmother''s home, discovering a trove of mysterious VHS tapes. When you press play on the vintage VHS player, you''re transported into the memories of the person behind the camera. As you step into the shoes of an individual from the past, you''ll unravel long-held family secrets, solve intriguing puzzles, and make choices that shape your history. Can you face the fear, confront the unknown, and connect the recorded memories to your own existence?' FROM games WHERE igdb_id = 342003 ON CONFLICT (game_id, language_code) DO NOTHING;
