INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('under-the-waves', 214402, '2023-08-29', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co545p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1tgy.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Under the Waves', 'Under the Waves is a narrative-driven adventure game about the engulfing power of grief. Set in the depths of the North Sea in a techno-futuristic 1970s, professional diver Stan is struggling to overcome a life-changing loss and embrace a new future. The isolation of the deep sea is a fitting manifestation of his state of mind, and as Stan retreads further into his self-imposed solitude, he starts to experience strange events far beneath the waves. Stuck between life and death, Stan will have to make the most significant choice of his existence.' FROM games WHERE igdb_id = 214402 ON CONFLICT (game_id, language_code) DO NOTHING;
