INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('their-majesties-pleasure', 250993, '2023-06-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6rqs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2bv8.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Their Majesties'' Pleasure', 'Pursue love and glory with unruly royals, seductive Fae, and rogue assassins in this epic text-based RPG romance set in a kingdom on the brink of war. As a member of the royal guard, it is your duty to protect the heirs to the throne, but the rebellious siblings lead you on a merry chase outside the palace. They open you up to a world that you never knew before: a secret network of assassins, corrupt city officials, and a cabaret brimming with songs, spirits, and sex. And when you are done carousing in the city, you can move into the dark of the magic-filled forest, where demigods and Fae throw jubilant, bacchanal revels, which include orgies for those so inclined' FROM games WHERE igdb_id = 250993 ON CONFLICT (game_id, language_code) DO NOTHING;
