INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pogger''s Legends', 'Pogger''s Legends is a turn based ''card'' game where you recruit heroes to defeat villains. The battle system is made from the ground up using elements that affect eachother, per-unit stats and unique abilities that can be battle decisive. There are an infinite amount of per-save generated stages and near infinite possible units. Save the day in Pogger''s Legends now!' FROM games WHERE igdb_id = 319641 ON CONFLICT (game_id, language_code) DO NOTHING;
