INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Planet Graveyard', 'Planet Graveyard is a short existential horror game based on a dream. It takes inspiration from LSD Dream Emulator and was originally created for the LSD Jam 2022. Explore bizarre and seemingly lifeless planet that looks like giant graveyard. Find out what actually happened to this world by interacting with different sights, scattered around. You are free to leave this planet whenever you want.' FROM games WHERE igdb_id = 323416 ON CONFLICT (game_id, language_code) DO NOTHING;
