INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reflection: The Greed', 'What''s the worst that can happen from reading a decrepit book? Jon Oz, who''s been sifting through pages of a book that shouldn''t even have its cover opened, is about to confine himself into a nightmare. Will you end the nightmare when darkness falls? Or will you be a prisoner to your own reflection?' FROM games WHERE igdb_id = 211712 ON CONFLICT (game_id, language_code) DO NOTHING;
