INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('square-enix-ai-tech-preview-the-portopia-serial-murder-case', 246605, '2023-04-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6enm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2a40.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Square Enix AI Tech Preview: The Portopia Serial Murder Case', 'This software is an educational demonstration of Natural Language Processing (NLP), an AI technology, as applied to the adventure game “The Portopia Serial Murder Case” (created by Yuji Horii and first published in Japan in 1983). At the time of the game’s original release, most adventure games were played using a “command input” system, where the player was asked to type in text to decide the actions of their character. Free text input systems like these allowed players to feel a great deal of freedom. However, they did come with one common source of frustration: players knowing what action they wanted to perform but being unable to do so because they could not find the right wording. This problem was caused by the limitations of PC performance and NLP technology of the time.' FROM games WHERE igdb_id = 246605 ON CONFLICT (game_id, language_code) DO NOTHING;
