INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chanye''s Home', 'Lam ChoTung, who runs a maid cafe in Shenzhen, discovered a girl sitting unconscious on the ground at the storefront as she prepared to return home from the shop. This girl not only had unclear consciousness but was also dressed in peculiar maid attire. This is a love story about these two girls.' FROM games WHERE igdb_id = 280151 ON CONFLICT (game_id, language_code) DO NOTHING;
