INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Incubus: A ghost-hunters tale', 'You are on your first solo ghost hunt, under the watchful instructions of Bear and Jen from the O.P.G paranormal team. Use real gadgets in a real location, a house investigated by the developers on the request of three different owners. It is a case worthy of a video game, so welcome to Incubus.' FROM games WHERE igdb_id = 221683 ON CONFLICT (game_id, language_code) DO NOTHING;
