INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baby''s Nightmare Circus VR: Remake', 'Baby''s Nightmare Circus VR: Remake is a re-imagining of the original Baby''s Nightmare Circus, optimized for virtual reality. This version features new 3D graphics and real-time rendering for an immersive and unsettling experience. It also offers a non-VR mode for PC, which includes support for 4K resolution, ray-tracing, and various ultrawide aspect ratios. The game''s environments have been fully rebuilt in 3D while retaining the aesthetic of the original, and the gameplay has been adapted for VR.' FROM games WHERE igdb_id = 336002 ON CONFLICT (game_id, language_code) DO NOTHING;
