INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Apocalypse Party', '"Apocalypse Party" is a 3D top-down action Roguelike game. It''s the brand-new sequel to "Plague Project Zero"! A new mission has begun! You will travel to the medieval era, where you''ll gradually master firearms, melee weapons, magic, cursed witchcraft, summoning, and more. Through your choices, equip yourself to become the ultimate survivor. Before the apocalypse arrives, have one last wild celebration with your teammates!' FROM games WHERE igdb_id = 277650 ON CONFLICT (game_id, language_code) DO NOTHING;
