INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cypher 007', 'Cypher 007 is a top-down mobile action game published by Tilting Point. Inspired by 60 years of Spycraft and Cypher 007, players will experience the world of Agent 007 to revisit Bond''s most iconic moments and locations. Players are tasked with defeating criminal mastermind Blofeld, head of Spectre, by gathering intel, uncovering secrets, and overcoming immersive levels filled with obstacles, opponents, and objectives that increase in difficulty as they progress. Compete against other 007 agents worldwide via leaderboards to prove who is on top.' FROM games WHERE igdb_id = 265647 ON CONFLICT (game_id, language_code) DO NOTHING;
