INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hao x Sora: The Sky''s Abound', 'Ride beyond imagination in Hao x Sora: The Sky''s Abound, the first action title in the Project Natura series. Rise as a hero out of their time and into the future of Natura, chasing down a old villain with unimaginable speed. Change the board - Equip a garage of hoverboards to store between runs and apply to different situations. Chase the world - Risk it all and choose when to end your run - either preserving your boards or bailing for a hell of a finish.' FROM games WHERE igdb_id = 274005 ON CONFLICT (game_id, language_code) DO NOTHING;
