INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blood West', 'Blood West is an immersive stealth shooter taking place in a nightmare version of a classic wild west setting. The player takes on the role of an outlawed gunslinger brought back to live by strange native spirits to find the root of a curse that has befallen the land. They will explore the dangerous frontier, gather supplies, expand their arsenal, and gain experience to unlock special traits, to best the many monsters and face off with challenging bosses.' FROM games WHERE igdb_id = 188555 ON CONFLICT (game_id, language_code) DO NOTHING;
