INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LesbiAnts', 'LesbiAnts: Our New Morphology is a retro horror-RPG made for the Game Boy! It features easy-to-use, menu-based combat, top-down exploration, and player upgrades in the form of biotic evolutions. Play through the story in about 45 minutes to 1 hour as your colony of Sisters fights to secure the mysterious seeds in each of 4 explorable areas. Try not to lose any Sisters in simple, yet rewarding combat against a variety of grotesque and unnerving creepy-crawlies. But even if one falls, the others must carry on and tend to both the Queen they love, and their new brood of rapidly-growing eggs~' FROM games WHERE igdb_id = 291593 ON CONFLICT (game_id, language_code) DO NOTHING;
