INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blasto X', 'In this new adventure, Blasto will have to explore various more or less familiar places and face tough opponents until confronting a nemesis believed to have been defeated for some time. Explore all the 13 levels and fight against the 5 bosses. Try your hand at an 80s-style scrolling beat''em up. Play matches like in the old days, Slap scum, AND ENKINDLE THIS!' FROM games WHERE igdb_id = 341386 ON CONFLICT (game_id, language_code) DO NOTHING;
