INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Idle Cinema Tycoon', 'Idle Cinema Tycoon is a casual business simulation game where you are in charge of your very own movie theater with the aim of slowly managing an empire of theaters. Purchase cinema halls, schedule screenings, and upgrade interiors to boost profits. Curate and collect films of various genres, liaise with guests in VIP rooms, and squeeze out as much profit as you can from ticket sales and more. Strategically expand your theater and complete missions to unlock valuable rewards!' FROM games WHERE igdb_id = 369567 ON CONFLICT (game_id, language_code) DO NOTHING;
