INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('out-of-scale-a-kurzgesagt-adventure', 272338, '2023-10-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7d7m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2ky7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Out of Scale: A Kurzgesagt Adventure', 'In this VR app, you explore the worlds within worlds around you from inside your mobile scale lab as you travel to five levels of scale - molecular, bacterial, insect, human, and mountain. You''re joined by STEVE, the lab''s AI assistant, who shows you the different effects of biology, physics, and chemistry in each realm. Together you''ll scan objects, find hidden ducks, and observe science in action. You will complete four missions around giant ants, a tardigrade, a protist, and giant fungi that have accidentally been scaled up by using scientific concepts and scaling objects up and down yourself.
