INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gig Life Tycoon', 'Struggling to make ends meet in the urban jungle is tough, but when you''re responsible for providing for your loved ones back home, the stakes are even higher. Welcome to our survival simulation game, where you take on the role of a migrant worker in a bustling metropolis. Day after day, you hustle to survive by taking on different gig jobs, each one bringing you closer to your goal of securing a better life for your family.' FROM games WHERE igdb_id = 256173 ON CONFLICT (game_id, language_code) DO NOTHING;
