INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Minds of Nations', 'After a number of incarnations on Earth and unhappy with the opportunities nations offer souls to grow, our hero, Kanli (you) is offered a chance to .. do better. He will try, over a number of simulations, to build a state, survive the hardships of time whilst helping as many souls as possible evolve beyond the taints.' FROM games WHERE igdb_id = 128985 ON CONFLICT (game_id, language_code) DO NOTHING;
