INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Folletti', 'In Folletti, step into the shoes of Yezac Folletti, who awakens to the horror of his wife being kidnapped by the sinister Degenite Church in the eerie land of Krycek. Embark on a quest across this bizarre realm, uncovering clues, forging alliances with quirky friends and peculiar creatures, and taking on odd quests. Unearth hidden conspiracies, brave terrifying territories, and perhaps find camaraderie in unexpected places.' FROM games WHERE igdb_id = 321321 ON CONFLICT (game_id, language_code) DO NOTHING;
