INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('up-the-hill-down-to-the-nevermind', 257210, '2023-07-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6sfr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scne3c.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Up the Hill Down to the Nevermind', 'Up the Hill Down to the Nevermind is a game about identity, girlhood, delusion, and memory. A lonely and depressed hikikomori grapples with their existence and transgender identity in a world where delusion begins to intertwine with reality. What once was good is now lost and all there is left is memory. But how reliable is your memory?' FROM games WHERE igdb_id = 257210 ON CONFLICT (game_id, language_code) DO NOTHING;
