INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teslagrad Remastered', 'Teslagrad Remastered is an updated version of the original Teslagrad, developed by Rain Games and released in 2023. This remastered edition features enhanced graphics, improved animations, and updated sound design while retaining the core puzzle-platforming mechanics of the original game. Players continue to use magnetism and electricity to navigate puzzles and obstacles within a mysterious tower, with the remastered version providing a refined visual and auditory experience.' FROM games WHERE igdb_id = 246407 ON CONFLICT (game_id, language_code) DO NOTHING;
