INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LazinAround', 'LazinAround is a puzzle game that will put your laser puzzling and color theory skills to the test. Master the increasingly complex puzzles by manipulating multiple lasers into a single color. Figure out how to combine different colored lasers together to hit the matching colored targets. Use the colored filter crystals to tune the lasers to the proper color. Hitting the matching colored target is the goal. Just don''t hit them with the wrong color.' FROM games WHERE igdb_id = 246122 ON CONFLICT (game_id, language_code) DO NOTHING;
