INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SCP: Bloodwater', 'SCP Bloodwater is a strategy management defense game inspired by the SCP Foundation''s SCP-354, also known as the Red Pool. Take the role of a newly appointed Site Director at the Red Pool Containment Zone, harvest valuable organic material, and defend the facility against the Red Pool''s attacks.' FROM games WHERE igdb_id = 272936 ON CONFLICT (game_id, language_code) DO NOTHING;
