INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Q.U.B.E. 2: Ultimate Edition', 'Includes ALL downloadable content for Q.U.B.E. 2: Classic Gloves, Lost Orbit, Aftermath. In Q.U.B.E. 2 you play as Amelia Cross, an archaeologist who has awoken among the ruins of an alien landscape. With the distant help of another survivor you must manipulate the structure of this mysterious world and find a way back home. As you explore and solve puzzles to progress, thought-provoking questions about your true purpose and the origins of the structure you are navigating will need to be considered, forcing you to come to terms with a devastating truth that will shake your world.' FROM games WHERE igdb_id = 233013 ON CONFLICT (game_id, language_code) DO NOTHING;
